  byline: 'c. 1320 · Italian medieval epic',
  titleAccent: 'a guided tour',
  hook: 'Halfway through the journey of his life, Dante found himself lost in a dark forest. A Roman poet arrived to guide him. They descended into Hell.',
  genre: ['Epic poetry', 'Medieval literature', 'Allegory'],
